import { test, expect } from '@playwright/test';
import { DOCS, PARENT_B, expectDocOpen, visibleText } from './legal-docs.helpers';

test.use({ storageState: PARENT_B });

test.describe('Юридические документы — родитель под входом', () => {
  test('Условия использования открываются под входом и переживают перезагрузку @desktop @prod-safe #d7fe2c', async ({ page }) => {
    // «מה קיים» шаг 2: раньше /consent?doc=terms уводил на /children
    await page.goto(DOCS.terms.url);
    await expectDocOpen(page, 'terms');

    await page.reload();
    await expectDocOpen(page, 'terms');
    // Контакт поддержки на экране документа (#c3aa39; F-01 «דרך לפנות לתמיכה»)
    await expect(visibleText(page, /support@benjico\.ai/)).toBeVisible();
    await expect(page).toHaveURL(DOCS.terms.urlRe);
  });
});
